private fun duration(ms:Long)="%02d:%02d".format(ms/3600000,(ms/60000)%60)
private fun longDuration(ms:Long)="${ms/3600000} óra ${(ms/60000)%60} perc"
private fun money(v:Long)=NumberFormat.getIntegerInstance(Locale("hu","HU")).format(v)+" Ft"
private fun time(v:Long)=java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(Date(v))
private fun openMap(context:Context,lat:Double?,lng:Double?,label:String,address:String=""){val query=if(lat!=null&&lng!=null)"$lat,$lng" else address.ifBlank{label};val url="https://www.google.com/maps/search/?api=1&query=${Uri.encode(query)}";context.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}
private fun openWaze(context:Context,place:LocationPlace){val target=if(place.latitude!=null&&place.longitude!=null)"ll=${place.latitude},${place.longitude}" else "q=${Uri.encode(place.officialAddress.ifBlank{place.name})}";val app=Uri.parse("waze://?$target&navigate=yes");val web=Uri.parse("https://waze.com/ul?$target&navigate=yes");runCatching{context.startActivity(Intent(Intent.ACTION_VIEW,app).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}.onFailure{context.startActivity(Intent(Intent.ACTION_VIEW,web).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}}
private fun openRoute(context:Context,points:List<GpsPoint>){val first=points.firstOrNull()?:return;val last=points.lastOrNull()?:first;val url="https://www.google.com/maps/dir/?api=1&origin=${first.latitude},${first.longitude}&destination=${last.latitude},${last.longitude}&travelmode=driving";context.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}
@Composable private fun LiveTick():Long{var n by remember{mutableLongStateOf(System.currentTimeMillis())};LaunchedEffect(Unit){while(true){delay(1000);n=System.currentTimeMillis()}};return n}
