@Composable fun SummaryCard(s:DaySummary,modifier:Modifier=Modifier,settings:AppSettings?=null){val metrics=buildList{if(settings?.showWorkTime!=false)add(SummaryMetric("Munkaidő",duration(s.workMillis),Green,Icons.Default.Schedule));if(settings?.showTravelTime!=false)add(SummaryMetric("Útidő",duration(s.travelMillis),Blue,Icons.Default.DirectionsCar));if(settings?.showEarnings!=false)add(SummaryMetric("Kereset",money(s.earnings),Orange,Icons.Default.Payments))};RRCard(modifier){if(metrics.isEmpty())Text("A főoldali összesítő ki van kapcsolva",Modifier.fillMaxWidth().padding(18.dp),textAlign=androidx.compose.ui.text.style.TextAlign.Center,color=DarkGray)else Row(Modifier.fillMaxWidth().padding(vertical=16.dp)){metrics.forEachIndexed{i,m->SummaryCell(m,Modifier.weight(1f));if(i<metrics.lastIndex)VerticalDivider(Modifier.height(66.dp),color=Border)}}}}
