@Composable private fun TodayScreen(vm:MainViewModel,onDetail:(Long)->Unit,onPlaces:()->Unit){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val places by vm.places.collectAsState();val now=LiveTick();val today=days.firstOrNull{it.day.date==LocalDate.now().toString()};val planFlow=remember(today?.day?.id){vm.repo.plans(today?.day?.id?:-1)};val plans by planFlow.collectAsState(initial=emptyList());val recommended=places.filter{p->plans.any{it.placeId==p.id&&!it.visited}};val ctx=LocalContext.current;var editEvent by remember{mutableStateOf<WorkEvent?>(null)};var manualType by remember{mutableStateOf<EventType?>(null)};val permissions=rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){};fun service(id:Long,start:Boolean){val i=Intent(ctx,TrackingService::class.java).setAction(if(start)TrackingService.ACTION_START else TrackingService.ACTION_STOP).putExtra(TrackingService.EXTRA_DAY,id);if(start)ctx.startForegroundService(i)else ctx.startService(i)};editEvent?.let{e->EventDialog(e,{editEvent=null},{vm.run{vm.repo.updateEvent(it)};editEvent=null},{vm.run{vm.repo.deleteEvent(e)};editEvent=null})};manualType?.let{type->ManualTimeDialog(type,{manualType=null}){ts->if(type==EventType.WORK_START&&today==null)vm.run{val id=vm.repo.startWork(ts);service(id,true)}else today?.let{d->vm.run{vm.repo.addEvent(d.day.id,type,ts)}};manualType=null}};LazyColumn(contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Ma – "+LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy. MMMM d., EEEE",Locale("hu"))),fontWeight=FontWeight.Bold,color=Navy,fontSize=14.sp)};if(recommended.isNotEmpty())item{RouteRecommendation(recommended,onPlaces)};if(today==null){item{SummaryCard(DaySummary(0,0,0,0.0,0),settings=settings)};item{RRCard(Modifier.fillMaxWidth()){WorkEventRow(EventType.WORK_START,null){manualType=EventType.WORK_START};WorkEventRow(EventType.TRIP_START,null);WorkEventRow(EventType.TRIP_END,null);AddTripRow{};WorkEventRow(EventType.WORK_END,null)}};item{PrimaryButton("Munkakezdés"){vm.run{val id=vm.repo.startWork();service(id,true)}}}}else{val sum=today.summary(settings,now);val events=today.events.sortedBy{it.timestamp};item{SummaryCard(sum,settings=settings)};item{RRCard(Modifier.fillMaxWidth()){events.forEach{e->WorkEventRow(e.type,e.timestamp){editEvent=e}};val last=events.lastOrNull()?.type;if(last==EventType.TRIP_START)WorkEventRow(EventType.TRIP_END,null){manualType=EventType.TRIP_END}else if(last!=EventType.WORK_END)AddTripRow{if(ContextCompat.checkSelfPermission(ctx,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)permissions.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.POST_NOTIFICATIONS));vm.run{vm.repo.nextAction(today.day.id);service(today.day.id,true)}};if(last!=EventType.WORK_END)WorkEventRow(EventType.WORK_END,null){manualType=EventType.WORK_END}}};item{OutlinedButton(onClick=onPlaces,modifier=Modifier.fillMaxWidth().height(54.dp),shape=RoundedCornerShape(10.dp)){Icon(Icons.Default.Place,null,Modifier.size(24.dp));Spacer(Modifier.width(10.dp));Text("Mai megállók",fontWeight=FontWeight.Bold)}};item{PrimaryButton("Térkép megnyitása"){onDetail(today.day.id)}}}}}
