@Composable private fun EarningsScreen(vm:MainViewModel){val days by vm.days.collectAsState();val settings by vm.settings.collectAsState();val now=LiveTick();val sums=days.map{it.summary(settings,now)};LazyColumn(contentPadding=PaddingValues(horizontal=12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{ScreenTitle("Kereset")};item{PeriodSelector()};item{RRCard(Modifier.fillMaxWidth()){Column(Modifier.fillMaxWidth().padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("Eddigi kereset (élő)",fontSize=12.sp,color=DarkGray);Text(money(sums.sumOf{it.earnings}),fontSize=30.sp,fontWeight=FontWeight.Bold,color=Green);Text("Aktuális időpont: ${time(now)}",fontSize=10.sp,color=DarkGray)}}};item{RRCard(Modifier.fillMaxWidth()){Row{EarningsCard("Munkaidő",longDuration(sums.sumOf{it.workMillis}),Green,Modifier.weight(1f));VerticalDivider(Modifier.height(70.dp));EarningsCard("Útidő (nettó)",longDuration(sums.sumOf{it.travelMillis}),Blue,Modifier.weight(1f))};HorizontalDivider();Row{EarningsCard("Óradíj",money(settings.hourlyRate),modifier=Modifier.weight(1f));VerticalDivider(Modifier.height(65.dp));EarningsCard("Ledolgozott napok","${days.size} nap",modifier=Modifier.weight(1f))}}}}}
