@Composable private fun ReportDialog(s:AppSettings,onDismiss:()->Unit,onSave:(AppSettings)->Unit){var mail by remember{mutableStateOf(s.reportEmail)};AlertDialog(onDismissRequest=onDismiss,title={Text("Jelentések és e-mail")},text={OutlinedTextField(mail,{mail=it},label={Text("Címzett e-mail")})},confirmButton={TextButton({onSave(s.copy(reportEmail=mail))}){Text("Mentés")}},dismissButton={TextButton(onDismiss){Text("Mégse")}})}
@Composable private fun ClosePeriodDialog(onDismiss:()->Unit,onClose:(String)->Unit){var date by remember{mutableStateOf(LocalDate.now().toString())};AlertDialog(onDismissRequest=onDismiss,title={Text("Időszak lezárása")},text={OutlinedTextField(date,{date=it},label={Text("Lezárás dátuma")})},confirmButton={TextButton({onClose(date)}){Text("Lezárás")}},dismissButton={TextButton(onDismiss){Text("Mégse")}})}

@Composable fun LocationRow(place:LocationPlace,checked:Boolean?=null,onClick:()->Unit){Row(Modifier.fillMaxWidth().height(64.dp).clickable(onClick=onClick).padding(horizontal=12.dp),verticalAlignment=Alignment.CenterVertically){if(checked!=null)Checkbox(checked,onCheckedChange={onClick()})else Icon(if(place.type==PlaceType.HOME)Icons.Default.Home else Icons.Default.Person,null,tint=if(place.type==PlaceType.HOME)Navy else Blue);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(place.name,fontWeight=FontWeight.Bold,fontSize=17.sp);if(place.officialAddress.isNotBlank())Text(place.officialAddress,fontSize=12.sp,color=DarkGray,maxLines=1)};Icon(Icons.Default.ChevronRight,null,tint=DarkGray,modifier=Modifier.size(18.dp))};HorizontalDivider(color=Border)}
@Composable private fun PlacesScreen(vm:MainViewModel,onBack:()->Unit){val places by vm.places.collectAsState();var editing by remember{mutableStateOf<LocationPlace?>(null)};if(editing!=null){PlaceEditor(editing!!,{editing=null}){vm.run{vm.repo.savePlace(it)};editing=null};return};LazyColumn{item{ScreenTitle("Megállók")};item{Box(Modifier.padding(12.dp)){PrimaryButton("+ Új megálló"){editing=LocationPlace(name="")}}};items(places){LocationRow(it){editing=it}}}}
@Composable private fun TodayPlacesScreen(vm:MainViewModel,onBack:()->Unit){val places by vm.places.collectAsState();val days by vm.days.collectAsState();val day=days.firstOrNull{it.day.date==LocalDate.now().toString()};val plans=day?.let{vm.repo.plans(it.day.id).collectAsState(initial=emptyList()).value}?:emptyList();var search by remember{mutableStateOf("")};LazyColumn{item{ScreenTitle("Mai megállók")};item{OutlinedTextField(search,{search=it},leadingIcon={Icon(Icons.Default.Search,null)},placeholder={Text("Keresés megállóra...")},modifier=Modifier.fillMaxWidth().padding(12.dp),shape=RoundedCornerShape(10.dp))};items(places.filter{it.name.contains(search,true)}){p->LocationRow(p,plans.any{it.placeId==p.id}){day?.let{d->vm.run{vm.repo.togglePlan(d.day.id,p.id,plans.none{it.placeId==p.id})}}}};if(plans.isNotEmpty())item{RouteRecommendation(places.filter{p->plans.any{it.placeId==p.id}})}}}
@Composable private fun RouteRecommendation(selected:List<LocationPlace>,onOther:()->Unit={}){val ctx=LocalContext.current;var index by remember(selected.map{it.id}){mutableIntStateOf(0)};var choosing by remember{mutableStateOf(false)};val next=selected.getOrNull(index%selected.size.coerceAtLeast(1));RRCard(Modifier.fillMaxWidth()){Column(Modifier.padding(14.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Navigation,null,tint=Green);Spacer(Modifier.width(8.dp));Text("Következő ajánlott megálló",fontSize=15.sp,fontWeight=FontWeight.SemiBold,color=DarkGray)};Spacer(Modifier.height(3.dp));Text(next?.name?:"Nincs kiválasztott megálló",fontWeight=FontWeight.Bold,fontSize=20.sp);Text(next?.officialAddress.orEmpty(),fontSize=12.sp,color=DarkGray);Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){PrimaryButton("Indulás Waze-zel",{next?.let{openWaze(ctx,it)}},Modifier.weight(1f));SecondaryButton("Másik megálló",{if(selected.isNotEmpty())choosing=true else onOther()},Modifier.weight(1f))}}};if(choosing)AlertDialog(onDismissRequest={choosing=false},title={Text("Mai megálló kiválasztása")},text={LazyColumn{itemsIndexed(selected){i,p->Row(Modifier.fillMaxWidth().clickable{index=i;choosing=false}.padding(vertical=11.dp),verticalAlignment=Alignment.CenterVertically){RadioButton(index==i,{index=i;choosing=false});Column{Text(p.name,fontWeight=FontWeight.Bold,fontSize=16.sp);Text(p.officialAddress,fontSize=11.sp,color=DarkGray)}}}}},confirmButton={TextButton({choosing=false}){Text("Bezárás")}})}

@Suppress("MissingPermission")
@Composable private fun PlaceEditor(place:LocationPlace,onBack:()->Unit,onSave:(LocationPlace)->Unit){
    val ctx=LocalContext.current
    var name by remember{mutableStateOf(place.name)};var address by remember{mutableStateOf(place.officialAddress)}
    var lat by remember{mutableStateOf(place.latitude?.toString()?:"")};var lng by remember{mutableStateOf(place.longitude?.toString()?:"")}
    var gate by remember{mutableStateOf(place.encryptedGateCode?:"")};var note by remember{mutableStateOf(place.note)}
    var radius by remember{mutableStateOf(place.recognitionRadiusMeters.toString())};var type by remember{mutableStateOf(place.type)}
    var keyPhoto by remember{mutableStateOf(place.photoPath)};var entrancePhoto by remember{mutableStateOf(place.entrancePhotoPath)}
    var pendingKeyPath by remember{mutableStateOf<String?>(null)};var pendingEntrancePath by remember{mutableStateOf<String?>(null)}
    fun newPhoto(prefix:String):Pair<Uri,String>{val dir=File(ctx.filesDir,"photos").apply{mkdirs()};val file=File(dir,"${prefix}_${System.currentTimeMillis()}.jpg");return FileProvider.getUriForFile(ctx,"${ctx.packageName}.files",file) to file.absolutePath}
    val keyCamera=rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()){ok->if(ok)keyPhoto=pendingKeyPath}
    val entranceCamera=rememberLauncherForActivityResult(ActivityResultContracts.TakePicture()){ok->if(ok)entrancePhoto=pendingEntrancePath}
    val locationClient=remember{LocationServices.getFusedLocationProviderClient(ctx)}
    fun readLocation(){locationClient.getCurrentLocation(com.google.android.gms.location.Priority.PRIORITY_HIGH_ACCURACY,null).addOnSuccessListener{p->p?.let{lat=it.latitude.toString();lng=it.longitude.toString()}}}
    val locationPermission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){if(it)readLocation()}
    Column(Modifier.verticalScroll(rememberScrollState()).padding(12.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){
        ScreenTitle(if(place.id==0L)"Új megálló" else "Megálló módosítása")
        Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){FilterChip(type==PlaceType.CLIENT,{type=PlaceType.CLIENT},{Text("Ügyfél")},leadingIcon={Icon(Icons.Default.Person,null)});FilterChip(type==PlaceType.HOME,{type=PlaceType.HOME},{Text("Home")},leadingIcon={Icon(Icons.Default.Home,null)})}
        Field(name,{name=it},"Név");Field(address,{address=it},"Hivatalos cím")
        Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){OutlinedTextField(lat,{lat=it},label={Text("GPS szélesség")},modifier=Modifier.weight(1f));OutlinedTextField(lng,{lng=it},label={Text("GPS hosszúság")},modifier=Modifier.weight(1f))}
        SecondaryButton("Jelenlegi koordináta kiolvasása"){if(ContextCompat.checkSelfPermission(ctx,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)readLocation()else locationPermission.launch(Manifest.permission.ACCESS_FINE_LOCATION)}
        SecondaryButton("Megnyitás térképen"){openMap(ctx,lat.toDoubleOrNull(),lng.toDoubleOrNull(),name,address)}
        Field(gate,{gate=it},"Kapukód")
        PhotoButton("Kulcsfotó",keyPhoto!=null,Icons.Default.Key){val p=newPhoto("key");pendingKeyPath=p.second;keyCamera.launch(p.first)}
        PhotoButton("Bejáratfotó",entrancePhoto!=null,Icons.Default.DoorFront){val p=newPhoto("entrance");pendingEntrancePath=p.second;entranceCamera.launch(p.first)}
        Field(note,{note=it},"Megjegyzés");Field(radius,{radius=it.filter(Char::isDigit)},"Felismerési sugár (méter)")
        PrimaryButton("Mentés"){if(name.isNotBlank())onSave(place.copy(type=type,name=name,officialAddress=address,latitude=lat.toDoubleOrNull(),longitude=lng.toDoubleOrNull(),encryptedGateCode=gate.ifBlank{null},photoPath=keyPhoto,entrancePhotoPath=entrancePhoto,note=note,recognitionRadiusMeters=radius.toIntOrNull()?:150))}
    }
}
@Composable private fun PhotoButton(label:String,saved:Boolean,icon:ImageVector,onClick:()->Unit){RRCard(Modifier.fillMaxWidth().clickable(onClick=onClick)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(icon,null,tint=DarkGray);Text("  $label",Modifier.weight(1f),fontWeight=FontWeight.Medium);if(saved){Icon(Icons.Default.CheckCircle,"Fénykép elmentve",tint=Green);Spacer(Modifier.width(8.dp))};Icon(Icons.Default.CameraAlt,"Fénykép készítése",tint=Blue)}}}
@Composable private fun Field(value:String,onChange:(String)->Unit,label:String){OutlinedTextField(value,onChange,label={Text(label)},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(9.dp))}

@Composable private fun DayDetail(vm:MainViewModel,id:Long,onBack:()->Unit){val day by vm.repo.observeDay(id).collectAsState(initial=null);val settings by vm.settings.collectAsState();var edit by remember{mutableStateOf<WorkEvent?>(null)};var add by remember{mutableStateOf(false)};val d=day?:return;val points=d.trips.firstOrNull()?.let{vm.repo.points(it.id).collectAsState(initial=emptyList()).value}?:emptyList();val ctx=LocalContext.current;edit?.let{EventDialog(it,{edit=null},{vm.run{vm.repo.updateEvent(it)};edit=null},{vm.run{vm.repo.deleteEvent(it)};edit=null})};if(add)AddEventDialog({add=false}){t,ts->vm.run{vm.repo.addEvent(id,t,ts)};add=false};LazyColumn(contentPadding=PaddingValues(12.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){item{ScreenTitle(d.day.date)};item{SummaryCard(d.summary(settings))};item{RRCard(Modifier.fillMaxWidth()){d.events.sortedBy{it.timestamp}.forEach{e->WorkEventRow(e.type,e.timestamp){edit=e}}}};item{SecondaryButton("+ Esemény hozzáadása"){add=true}};item{PrimaryButton(if(points.isEmpty())"Nincs rögzített útvonal" else "Útvonal megnyitása térképen"){if(points.isNotEmpty())openRoute(ctx,points)}}}}
@Composable private fun EventDialog(e:WorkEvent,onDismiss:()->Unit,onSave:(WorkEvent)->Unit,onDelete:()->Unit){var v by remember{mutableStateOf(Instant.ofEpochMilli(e.timestamp).atZone(ZoneId.systemDefault()).toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")))};val deletable=e.type==EventType.TRIP_START||e.type==EventType.TRIP_END;AlertDialog(onDismissRequest=onDismiss,title={Text("Esemény szerkesztése")},text={OutlinedTextField(v,{v=it},label={Text("Dátum és idő")})},confirmButton={TextButton({runCatching{LocalDateTime.parse(v,DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()}.getOrNull()?.let{onSave(e.copy(timestamp=it))}}){Text("Mentés")}},dismissButton={Row{if(deletable)TextButton(onDelete){Text("Törlés",color=Color.Red)};TextButton(onDismiss){Text("Mégse")}}})}
@Composable private fun ManualTimeDialog(type:EventType,onDismiss:()->Unit,onSave:(Long)->Unit){var v by remember{mutableStateOf(LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")))};val title=when(type){EventType.WORK_START->"Munkakezdés időpontja";EventType.TRIP_START->"Indulás időpontja";EventType.TRIP_END->"Visszaérkezés időpontja";EventType.WORK_END->"Munka vége időpontja"};AlertDialog(onDismissRequest=onDismiss,title={Text(title)},text={OutlinedTextField(v,{v=it},label={Text("Dátum és idő")})},confirmButton={TextButton({runCatching{LocalDateTime.parse(v,DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()}.getOrNull()?.let(onSave)}){Text("Mentés")}},dismissButton={TextButton(onDismiss){Text("Mégse")}})}
@Composable private fun AddEventDialog(onDismiss:()->Unit,onSave:(EventType,Long)->Unit){var type by remember{mutableStateOf(EventType.TRIP_START)};AlertDialog(onDismissRequest=onDismiss,title={Text("Esemény hozzáadása")},text={Column{EventType.entries.filter{it!=EventType.WORK_START}.forEach{Row(Modifier.clickable{type=it},verticalAlignment=Alignment.CenterVertically){RadioButton(type==it,{type=it});Text(when(it){EventType.WORK_START->"Munkakezdés";EventType.TRIP_START->"Útra indulás";EventType.TRIP_END->"Visszaérkezés";EventType.WORK_END->"Munka vége"})}}}},confirmButton={TextButton({onSave(type,System.currentTimeMillis())}){Text("Hozzáadás")}},dismissButton={TextButton(onDismiss){Text("Mégse")}})}
